head.script:
scwin.showMessage = function(message) {
    //  WebSquare.logger.printLog(message);
    console.log(message);
    // alert(message);
}
scwin.gridView1_oncellclick = function(row, col) {
    scwin.showMessage('== oncellclick ==\n[row] = ' + row + '\n[col] = ' + col);
};
scwin.gridView1_onsubtotalclick = function(info) {
    scwin.showMessage('== onsubtotalclick ==\n[colID] = ' + info.colID + ', [startRowIndex] = ' + info.startRowIndex + ', [endRowIndex] = ' + info.endRowIndex + '\n[element] = ' + info.element.outerHTML);
};
scwin.gridView1_onsubtotaldblclick = function(info) {
    scwin.showMessage('== onsubtotaldblclick ==\n[colID] = ' + info.colID + ', [startRowIndex] = ' + info.startRowIndex + ', [endRowIndex] = ' + info.endRowIndex + '\n[element] = ' + info.element.outerHTML);
};
scwin.__isEl = function() {
    return el = WebSquare.wUnit.getJq('#gridView1_body_tbody tr');
}
scwin.rgb2hex = function(rgb) {
    rgb = rgb.match(/^rgba?[\s+]?\([\s+]?(\d+)[\s+]?,[\s+]?(\d+)[\s+]?,[\s+]?(\d+)[\s+]?/i);
    return (rgb && rgb.length === 4) ? '#' +
        ('0' + parseInt(rgb[1], 10).toString(16)).slice(-2) +
        ('0' + parseInt(rgb[2], 10).toString(16)).slice(-2) +
        ('0' + parseInt(rgb[3], 10).toString(16)).slice(-2) : "";
}
scwin.checkTopColor = function() {
    if (navigator.userAgent.indexOf("Firefox") > -1) {
        var color = WebSquare.wUnit.getJq($('.w2grid_lastRow').last()).css('borderTopColor');
    } else {
        var color = WebSquare.wUnit.getJq($('.w2grid_lastRow').last()).css('border-top-color');
    }
    if (color.indexOf('rgb') > -1) {
        color = scwin.rgb2hex(color);
    }
    return color == '#ff0000' || color == 'red';
}
scwin.checkBackgroundColor = function() {
    var backgroundColor = WebSquare.wUnit.getJq($('.w2grid_lastRow').last()).css('background-color');
    if (backgroundColor.indexOf('rgb') > -1) {
        backgroundColor = scwin.rgb2hex(backgroundColor);
    }
    return backgroundColor == '#ffff00' || backgroundColor == 'yellow';
}
scwin.checkVal1 = function() {
    return WebSquare.wUnit.getJq($('.w2grid_lastRow').last()).css('border-top-style') == 'solid';
};
scwin.checkVal2 = function() {
    return Math.ceil(WebSquare.wUnit.getJq($('.w2grid_lastRow').last()).css('border-top-width').split('px')[0]) == 2;
};
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();

    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1').setBottomRowIndex(100)");
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("assert", "scwin.checkTopColor()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkBackgroundColor()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();

scwin.onpageload = function() {
    window.data = [];
    for (var i = 0; i < 100; i++) {
        data.push(i);
        data.push(Math.floor(i / 3));
        data.push(i * i);
    }
    dataList1.setData(data);
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 26-Feb-2018
    //End unitTest
}
